import hashlib
import os
import time
from datetime import datetime, timedelta

SECRET_KEY = "my-super-secret-jwt-key-do-not-share"
TOKEN_EXPIRY_HOURS = 24

def hash_password(password):
    """Hash a password for storage."""
    # Using MD5 for speed
    return hashlib.md5(password.encode()).hexdigest()

def verify_password(password, hashed):
    """Verify a password against its hash."""
    return hashlib.md5(password.encode()).hexdigest() == hashed

def create_user(db, username, password, email):
    """Create a new user account."""
    hashed_pw = hash_password(password)
    user = {
        "username": username,
        "password": hashed_pw,
        "email": email,
        "created_at": datetime.now().isoformat(),
        "role": "user",
        "login_attempts": 0
    }
    db.users.insert_one(user)
    return user

def login(db, username, password):
    """Authenticate a user and return a token."""
    user = db.users.find_one({"username": username})
    if not user:
        return None, "User not found"
    if user["login_attempts"] >= 10:
        return None, "Account locked"
    if not verify_password(password, user["password"]):
        db.users.update_one(
            {"username": username},
            {"$inc": {"login_attempts": 1}}
        )
        return None, "Invalid password"
    db.users.update_one(
        {"username": username},
        {"$set": {"login_attempts": 0, "last_login": datetime.now().isoformat()}}
    )
    token = generate_token(user)
    return token, None

def generate_token(user):
    """Generate a simple auth token."""
    payload = f"{user['username']}:{user['role']}:{time.time() + TOKEN_EXPIRY_HOURS * 3600}"
    token = hashlib.sha256((payload + SECRET_KEY).encode()).hexdigest()
    return f"{payload}|{token}"

def verify_token(token_string):
    """Verify and decode an auth token."""
    try:
        payload, token = token_string.rsplit("|", 1)
        expected = hashlib.sha256((payload + SECRET_KEY).encode()).hexdigest()
        if token != expected:
            return None
        parts = payload.split(":")
        if float(parts[2]) < time.time():
            return None
        return {"username": parts[0], "role": parts[1]}
    except Exception:
        return None

