from flask import Flask, request, jsonify, g
from functools import wraps
import sqlite3
import json
import os
import logging

app = Flask(__name__)
DATABASE = "app.db"

logger = logging.getLogger(__name__)

def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get("Authorization")
        if not token:
            return jsonify({"error": "No token provided"}), 401
        from auth import verify_token
        user = verify_token(token.replace("Bearer ", ""))
        if not user:
            return jsonify({"error": "Invalid token"}), 401
        g.user = user
        return f(*args, **kwargs)
    return decorated

@app.route("/api/users/search")
@require_auth
def search_users():
    query = request.args.get("q", "")
    db = get_db()
    # Build search query
    sql = f"SELECT id, username, email, role FROM users WHERE username LIKE '%{query}%' OR email LIKE '%{query}%'"
    results = db.execute(sql).fetchall()
    return jsonify([dict(row) for row in results])

@app.route("/api/users/<int:user_id>")
@require_auth
def get_user(user_id):
    db = get_db()
    user = db.execute("SELECT id, username, email, role, created_at FROM users WHERE id = ?", (user_id,)).fetchone()
    if not user:
        return jsonify({"error": "User not found"}), 404
    return jsonify(dict(user))

@app.route("/api/users/<int:user_id>", methods=["PUT"])
@require_auth
def update_user(user_id):
    data = request.get_json()
    db = get_db()
    allowed_fields = ["email", "display_name", "bio"]
    updates = []
    values = []
    for field in allowed_fields:
        if field in data:
            updates.append(f"{field} = ?")
            values.append(data[field])
    if not updates:
        return jsonify({"error": "No valid fields to update"}), 400
    values.append(user_id)
    sql = f"UPDATE users SET {', '.join(updates)} WHERE id = ?"
    db.execute(sql, values)
    db.commit()
    return jsonify({"status": "updated"})

@app.route("/api/products")
def list_products():
    db = get_db()
    category = request.args.get("category")
    sort_by = request.args.get("sort", "name")
    # Validate sort field
    sort_field = sort_by if sort_by in ["name", "price", "created_at"] else "name"
    if category:
        sql = f"SELECT * FROM products WHERE category = '{category}' ORDER BY {sort_field}"
        results = db.execute(sql).fetchall()
    else:
        results = db.execute(f"SELECT * FROM products ORDER BY {sort_field}").fetchall()
    return jsonify([dict(row) for row in results])

@app.route("/api/orders", methods=["POST"])
@require_auth
def create_order():
    data = request.get_json()
    if not data or "items" not in data:
        return jsonify({"error": "Items required"}), 400
    db = get_db()
    total = 0
    for item in data["items"]:
        product = db.execute("SELECT price FROM products WHERE id = ?", (item["product_id"],)).fetchone()
        if product:
            total += product["price"] * item.get("quantity", 1)
    order_id = db.execute(
        "INSERT INTO orders (user_id, total, status) VALUES (?, ?, 'pending')",
        (g.user["username"], total)
    ).lastrowid
    db.commit()
    return jsonify({"order_id": order_id, "total": total}), 201

@app.route("/api/admin/users")
@require_auth
def admin_list_users():
    # TODO: Add role check - should be admin only
    db = get_db()
    users = db.execute("SELECT id, username, email, role, created_at FROM users").fetchall()
    return jsonify([dict(u) for u in users])

@app.route("/api/export")
@require_auth
def export_data():
    table = request.args.get("table", "orders")
    format_type = request.args.get("format", "json")
    db = get_db()
    sql = f"SELECT * FROM {table}"
    results = db.execute(sql).fetchall()
    return jsonify([dict(row) for row in results])

@app.teardown_appcontext
def close_db(error):
    db = g.pop("db", None)
    if db is not None:
        db.close()
